// This file is generated by running: dart run build_runner build
part 'database.g.dart';

enum RecurrenceType { never, daily, weekly, monthly, yearly, custom }

// Converter for RecurrenceType
class RecurrenceTypeConverter extends TypeConverter<RecurrenceType, String> {
  const RecurrenceTypeConverter();
  @override
  RecurrenceType fromSql(String fromDb) => RecurrenceType.values.firstWhere((e) => e.name == fromDb);
  @override
  String toSql(RecurrenceType value) => value.name;
}

// Converter for Custom Weekdays (e.g., [1, 3, 5] for Mon, Wed, Fri)
class IntListConverter extends TypeConverter<List<int>, String> {
  const IntListConverter();
  @override
  List<int> fromSql(String fromDb) => List<int>.from(json.decode(fromDb));
  @override
  String toSql(List<int> value) => json.encode(value);
}

@DataClassName('Alarm')
class Alarms extends Table {
  IntColumn get id => integer().autoIncrement()();
  TextColumn get title => text().withLength(min: 1, max: 100)();
  DateTimeColumn get originalDate => dateTime()();
  IntColumn get scheduledHour => integer()();
  IntColumn get scheduledMinute => integer()();
  
  TextColumn get recurrenceType => text().map(const RecurrenceTypeConverter())();
  TextColumn get customWeekdays => text().map(const IntListConverter()).nullable()();
  
  // NEW: Stores a list of integer offsets in minutes (e.g., [60, 1440] for 1hr and 1day before)
  TextColumn get preAlertOffsets => text().map(const IntListConverter()).withDefault(const Constant('[]'))();
  
  BoolColumn get isEnabled => boolean().withDefault(const Constant(true))();
  TextColumn get soundId => text().withDefault(const Constant('default'))();
  IntColumn get snoozeDuration => integer().withDefault(const Constant(5))();
  
  DateTimeColumn get createdAt => dateTime().withDefault(currentDateAndTime)();
  DateTimeColumn get updatedAt => dateTime().withDefault(currentDateAndTime)();
}

@DriftDatabase(tables: [Alarms])
class DontForgetDatabase extends _$DontForgetDatabase {
  DontForgetDatabase() : super(_openConnection());

  @override
  int get schemaVersion => 1;

  // Repositories for UI state
  Stream<List<Alarm>> watchAlarmsForDate(DateTime date) {
    // This will be expanded in Phase 5 to account for recurrence rules
    return select(alarms).watch();
  }

  Future<int> insertAlarm(AlarmsCompanion alarm) => into(alarms).insert(alarm);
  Future<bool> updateAlarm(Alarm alarm) => update(alarms).replace(alarm);
  Future<int> deleteAlarm(int id) => (delete(alarms)..where((a) => a.id.equals(id))).go();
}

LazyDatabase _openConnection() {
  return LazyDatabase(() async {
    final dbFolder = await getApplicationDocumentsDirectory();
    final file = File(p.join(dbFolder.path, 'dontforget.sqlite'));
    return NativeDatabase.createInBackground(file);
  });
}